<div class="panel mt-section" id="finance-cfu-directory"><div class="section-title">Справочник ЦФУ</div><div class="page-summary"><span>Единый справочник для ручного и автоматического разнесения.</span></div><form method="post" action="<?= app_url('/company/finance/settings/matching-rules/cfu/save') ?>" class="form-inline mt-section"><?= csrfField() ?><input class="field-input" name="name" required placeholder="Название ЦФУ"><input class="field-input" type="number" name="sort_order" value="100" min="0" max="100000"><button class="btn btn-secondary" type="submit">Добавить ЦФУ</button></form><?php if(!empty($cashFlowCenters)): ?><div class="table-scroll mt-section"><table class="table"><thead><tr><th>ЦФУ</th><th>Порядок</th><th>Статус</th><th></th></tr></thead><tbody><?php foreach($cashFlowCenters as $cfu): ?><tr><td><?= e($cfu['name']) ?></td><td class="col-mono"><?= (int)$cfu['sort_order'] ?></td><td><?= !empty($cfu['is_active'])?'Активен':'Отключён' ?></td><td><form method="post" action="<?= app_url('/company/finance/settings/matching-rules/cfu/toggle') ?>" class="inline-form"><?= csrfField() ?><input type="hidden" name="id" value="<?= (int)$cfu['id'] ?>"><input type="hidden" name="active" value="<?= !empty($cfu['is_active'])?'0':'1' ?>"><button type="submit" class="btn btn-ghost btn-sm"><?= !empty($cfu['is_active'])?'Отключить':'Включить' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<template id="rule-remove-template"><form method="post" action="<?= app_url('/company/finance/settings/matching-rules/remove') ?>" class="inline-form" data-rule-remove><?= csrfField() ?><input type="hidden" name="id"><button type="submit" class="btn btn-ghost btn-sm btn-action" title="Удалить правило">×</button></form></template>
<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('[data-edit-id]').forEach(function(edit){var row=edit.closest('tr'),cell=edit.closest('.col-actions'),tpl=document.getElementById('rule-remove-template');if(row&&row.cells[5]&&row.cells[5].textContent.indexOf('transfer_to_cash')>=0)row.cells[5].textContent='Банк → Касса';if(!cell||!tpl||cell.querySelector('[data-rule-remove]'))return;var f=tpl.content.firstElementChild.cloneNode(true);f.querySelector('input[name=id]').value=edit.dataset.editId;f.addEventListener('submit',function(e){if(!confirm('Удалить правило?'))e.preventDefault();});cell.appendChild(f);});});</script>
